#!/usr/bin/env ruby
# frozen_string_literal: true

require "yaml"

repo_root = File.expand_path("../../..", __dir__)
config_path = ARGV[0] || File.join(repo_root, "config.yml")
out_path = ARGV[1] || File.join(__dir__, "node_locations.inc")

config = YAML.load_file(config_path)
lines = [
  "/*----------------------------------------------------------------------------*/",
  "/* This file is generated by test/fuzz/harness/gen_node_locations.rb from     */",
  "/* config.yml and should not be modified manually.                            */",
  "/*----------------------------------------------------------------------------*/",
  ""
]

config.fetch("nodes").each do |node|
  loc_fields = (node["fields"] || []).select { |f| f["type"] == "location" || f["type"] == "location?" }
  next if loc_fields.empty?

  human = node.fetch("name").gsub(/(?<=.)[A-Z]/, "_\\0").downcase
  lines << "    case PM_#{human.upcase}: {"
  lines << "        const pm_#{human}_t *cast = (const pm_#{human}_t *) node;"
  loc_fields.each do |field|
    fname = field.fetch("name")
    lines << "        fuzz_check_sub_location(node, \"#{fname}\", cast->#{fname}, ctx);"
  end
  lines << "        break;"
  lines << "    }"
end

contents = lines.join("\n") + "\n"
abort("Non-ASCII character in generated #{out_path}") unless contents.ascii_only?

tmp_path = "#{out_path}.tmp.#{$$}"
File.write(tmp_path, contents)
File.rename(tmp_path, out_path)
